`timescale 1ns/1ps
// =============================================================================
// tb_simple.v
// Write-relay verification using DYNAMICALLY GENERATED bytes each iteration
// (via $random), not hardcoded literals. For every iteration:
//   1. generate a random byte
//   2. write it into the bridge over I2C (SDA)
//   3. independently capture the ACTUAL bits shifted out on MOSI (not an
//      internal register -- the real physical wire)
//   4. reconstruct the MOSI byte and compare it against the random source
//      byte that was never typed in advance
// This proves the bridge relays arbitrary real-time data correctly, rather
// than only working for a canned set of test constants.
// =============================================================================
module tb_simple;

    reg clk = 0;
    always #10 clk = ~clk;

    reg key0 = 0;
    wire rst_n;
    reset_sync u_rst (.clk(clk), .rst_n_async(key0), .rst_n_sync(rst_n));
    initial begin key0 = 0; #200; key0 = 1; end

    wire sda, scl;
    pullup(sda);
    pullup(scl);
    reg sda_drv = 1, scl_drv = 1;
    assign sda = sda_drv ? 1'bz : 1'b0;
    assign scl = scl_drv ? 1'bz : 1'b0;
    localparam HALF = 500;

    wire [1:0] reg_ptr;
    wire [7:0] wr_data, rd_data;
    wire wr_pulse, byte_rdy_tgl, rd_pulse;

    i2c_slave #(.I2C_ADDR(7'h50)) u_i2c (
        .clk(clk), .rst_n(rst_n), .sda(sda), .scl_pad(scl),
        .reg_ptr(reg_ptr), .wr_data(wr_data), .wr_pulse(wr_pulse),
        .byte_rdy_tgl(byte_rdy_tgl), .rd_data(rd_data), .rd_pulse(rd_pulse)
    );

    wire [7:0] spi_tx, spi_rx;
    wire spi_start, spi_busy, spi_done;
    wire sck, mosi, miso, cs_n;

    spi_master #(.CLK_DIV(5)) u_spi (
        .clk(clk), .rst_n(rst_n), .sck(sck), .mosi(mosi), .miso(miso), .cs_n(cs_n),
        .tx_byte(spi_tx), .rx_byte(spi_rx), .start(spi_start), .busy(spi_busy), .done(spi_done)
    );

    wire status_busy, status_done, status_err;

    bridge_fsm #(.FIFO_DEPTH(32)) u_fsm (
        .clk(clk), .rst_n(rst_n),
        .reg_ptr(reg_ptr), .wr_data(wr_data), .wr_pulse(wr_pulse), .rd_pulse(rd_pulse),
        .rd_data(rd_data), .spi_tx(spi_tx), .spi_start(spi_start),
        .spi_rx(spi_rx), .spi_busy(spi_busy), .spi_done(spi_done),
        .STATUS_busy(status_busy), .STATUS_done(status_done), .STATUS_err(status_err)
    );

    // ---- passive MOSI capture: reconstructs the actual byte shifted out on
    // the real wire, completely independent of any internal register ----
    reg [7:0] mosi_captured;
    reg [3:0] mosi_bitcnt;
    always @(negedge cs_n) mosi_bitcnt = 0;
    always @(posedge sck) if (!cs_n) begin
        mosi_captured = {mosi_captured[6:0], mosi};
        mosi_bitcnt = mosi_bitcnt + 1;
    end

    // dummy SPI slave (not under test here -- MISO content is irrelevant
    // for a write-relay check, tie it off)
    assign miso = 1'bz;

    task i2c_start; begin sda_drv=1; scl_drv=1; #HALF; sda_drv=0; #HALF; scl_drv=0; #HALF; end endtask
    task i2c_stop; begin sda_drv=0; #HALF; scl_drv=1; #HALF; sda_drv=1; #HALF; end endtask

    task i2c_send(input [7:0] d);
        integer i;
        begin
            for (i=7;i>=0;i=i-1) begin sda_drv=d[i]; #HALF; scl_drv=1; #HALF; scl_drv=0; end
            sda_drv=1; #HALF; scl_drv=1; #HALF; scl_drv=0;
        end
    endtask

    integer pass_count = 0, fail_count = 0;

    task check(input [8*20-1:0] name, input [7:0] got, input [7:0] exp);
        begin
            if (got === exp) begin pass_count=pass_count+1; $display("[PASS] %0s got=0x%02h", name, got); end
            else begin fail_count=fail_count+1; $display("[FAIL] %0s got=0x%02h expected=0x%02h", name, got, exp); end
        end
    endtask

    // one write-relay round trip using a byte the testbench generates AT
    // RUN TIME -- never typed as a literal anywhere in this file
    task run_relay_test(input integer iter_num);
        reg [7:0] random_byte;
        begin
            random_byte = $random;   // <-- the actual "real-time" data source
            $display("--- iteration %0d: source byte (generated at run time) = 0x%02h ---", iter_num, random_byte);

            i2c_start; i2c_send({7'h50,1'b0}); i2c_send(8'h02); i2c_send(random_byte); i2c_stop; #500;
            i2c_start; i2c_send({7'h50,1'b0}); i2c_send(8'h01); i2c_send(8'd1);         i2c_stop; #500;
            i2c_start; i2c_send({7'h50,1'b0}); i2c_send(8'h00); i2c_send(8'h80);         i2c_stop; #500; // write mode, GO

            wait(status_done); #200;

            check("relay_status_done", status_done, 1'b1);
            check("relay_status_err_clear", status_err, 1'b0);
            check("relay_mosi_matches_source", mosi_captured, random_byte);

            #500;
        end
    endtask

    integer i;
    initial begin
        wait(rst_n); #200;

        // 20 iterations, each with a genuinely different, run-time-generated
        // byte -- not a fixed table of literals
        for (i = 0; i < 20; i = i + 1) begin
            run_relay_test(i);
        end

        $display("========================================");
        $display(" PASSED: %0d   FAILED: %0d", pass_count, fail_count);
        $display("========================================");
        if (fail_count == 0) $display("*** ALL TESTS PASSED WITH DYNAMIC DATA ***");
        else $display("*** %0d TEST(S) FAILED ***", fail_count);
        $finish;
    end

    initial begin #5_000_000; $display("[TIMEOUT]"); $finish; end

endmodule
